"""Extract the lookup tables from libv4lconvert's spca561-decompress.c
and write them as a Python module (spca561cam/_tables.py)."""
import re
import sys

src = open(sys.argv[1], encoding="utf-8").read()
names = ["nbits_A", "tab_A", "nbits_B", "tab_B", "nbits_C", "tab_C",
         "nbits_D", "tab_D", "a_curve", "clamp0_255", "abs_clamp15",
         "diff_encoding"]
out = ['"""Lookup tables for the SPCA561 decoder.\n\n'
       'Generated by tools/gen_tables.py from libv4lconvert/spca561-decompress.c\n'
       '(C) 2005 Andrzej Szombierski, LGPL-2.1-or-later. Do not edit by hand.\n"""\n'
       'import numpy as np\n']
for name in names:
    m = re.search(r"\b" + name + r"\[\]\s*=\s*\{(.*?)\};", src, re.S)
    vals = [int(v, 0) for v in re.findall(r"-?(?:0x[0-9a-fA-F]+|\d+)", m.group(1))]
    out.append(f"{name.upper()} = np.array({vals}, dtype=np.int32)  # len {len(vals)}\n")
    print(name, len(vals))
open(sys.argv[2], "w", encoding="utf-8").write("\n".join(out))
